      background: rgba(255, 255, 255, 0.12);
      border-color: var(--graph-border-active);
      transform: translateY(-1px);
  }

  .object-name:focus {
      border: 1px solid rgba(88, 166, 255, 0.55);
  }

  .object-name:active {
      background: rgba(255, 255, 255, 0.18);
      transform: translateY(0);
  }

  .widget-shell {
