direct msg ƒ:
(peerId, data) => {
    const opcodes = diarsaba.get('ws opcodes :');
    const encodeFrame = diarsaba.get('encode frame ƒ');
    const sendWs = diarsaba.get('send ws ƒ');
    const textBytes = diarsaba.get('ws text bytes ƒ');
    const u16 = diarsaba.get('ws u16 ƒ');
    const concat = diarsaba.get('ws concat ƒ');
    const randomBytes = diarsaba.get('ws random bytes ƒ');

    const peerBytes = textBytes(peerId);
    const dataBytes = textBytes(data);
    const payload = concat(u16(peerBytes.length), peerBytes, dataBytes);
    const id = randomBytes(16);
    const frame = encodeFrame(opcodes.DIRECT_MSG, id, payload);
    sendWs(frame, id, opcodes.DIRECT_MSG);
}

